import json,datetime,pathlib,copy
p=pathlib.Path(__file__).parent
g=json.loads((p/'dag.json').read_text()); before=copy.deepcopy(g)
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
pg='https://www.postgresql.org/docs/current/transaction-iso.html'
tx='https://www.postgresql.org/docs/current/tutorial-transactions.html'
my='https://dev.mysql.com/doc/refman/8.4/en/innodb-transaction-isolation-levels.html'
sq='https://www.sqlite.org/isolation.html'
mv='https://www.postgresql.org/docs/current/mvcc-intro.html'
rt='https://www.postgresql.org/docs/current/mvcc-serialization-failure-handling.html'
def ev(url,loc,claim,kind='direct'):return dict(url=url,locator=loc,claim=claim,access='Relevant HTML passage directly read in this run',kind=kind)
n={x['id']:x for x in g['nodes']}
def edit(id,a,e):n[id].update(answer=a,status='supported',evidence=e)
edit('atomicity','Atomicity means all of a transaction’s stored changes survive together or none do. It does not determine whether a later statement sees a newer committed transaction.',[ev(tx,'3.4, paragraphs following transfer example','A failed transaction leaves none of its grouped changes.'),ev(pg,'13.2.1, opening two paragraphs','Statements within one transaction may see different committed data.')])
edit('concurrency','Separate connections—separate conversations between application and database—can each have an unfinished transaction. One can read, another update and commit, and the first then read or update. Overlap needs no simultaneous CPU execution.',[ev(sq,'Isolation And Concurrency, X/Y example','X can keep a read transaction open while Y updates and commits.'),ev(pg,'13.2.3, two concurrent sum transactions','Reads and dependent writes can interleave across transactions.')])
edit('read_decision','The application can choose later SQL and its values using earlier query results. A concurrent transaction can change relevant data between that read and the later write; the application’s decision may then describe an earlier state.',[ev(rt,'13.5, complete-transaction retry paragraph','Transaction logic includes deciding which SQL and values to use.'),ev(pg,'13.2.3, sum example','Concurrent transactions each insert values chosen from earlier sums.')])
edit('snapshot','A read snapshot selects which stored row versions a statement may observe. A version is the row’s values from a particular update; retaining earlier versions allows a read to use earlier committed data even after newer updates exist. A transaction also sees its own prior changes. The isolation policy chooses the snapshot’s reference point.',[ev(mv,'13.1, opening paragraph','MVCC exposes a database version from an earlier point.'),ev(pg,'13.2.1–13.2.2, opening paragraphs','Statement-level versus transaction-level snapshots and own-write visibility.')])
edit('wrong_result','Two transactions can each read that a shared rule permits their change, then write different rows. Each choice is correct against what it read; together the committed writes can break the rule. No dirty read or partially committed transaction is necessary.',[ev(pg,'13.2.3, concurrent sums and serial comparison','Independent read-dependent writes can both commit at Repeatable Read with no equivalent serial ordering.'),ev(pg,'13.2.3, paragraph beginning “The guarantee that any set”','Serial execution of individually correct transactions explains preservation of correctness.')])
n['wrong_result']['examples']=[{'type':'constructed reasoning example, not a measured database run','given_inputs':['Rows A and B initially both have on_call=true.','Rule: at least one row remains on call.','Each transaction reads both rows; only if the other row is true does it set its own row false.','Ordinary reads; separate connections; no extra locks, constraint, or third writer.'],'overlap':['A reads both true.','B reads both true.','A sets only A false.','B sets only B false.','Both commit under a policy allowing these read/write dependencies.'],'result':'Both false violates the rule; each transaction alone from the initial state would preserve it.','serial_comparison':'A then B leaves B true, because B observes A false and does not leave. B then A leaves A true. Neither serial order produces both false.','qualification':'Illustrates PostgreSQL Repeatable Read’s possible cross-row serialization anomaly by applying documented snapshot and update rules. Not a guarantee that every engine called Repeatable Read permits this schedule.'}]
edit('levels','Minimum protections: Read Uncommitted may permit dirty reads; Read Committed forbids those but may permit nonrepeatable and phantom reads; Repeatable Read additionally forbids nonrepeatable reads, but may permit phantoms; Serializable also forbids phantoms and all serialization anomalies. Engines may provide stronger protection than these minimums.',[ev(pg,'13.2, Table 13.1 and following implementation paragraphs','Four named levels specify forbidden phenomena, with stronger PostgreSQL behavior at two levels.')])
edit('locks','A lock records a transaction’s protected access to data. An incompatible request—such as a second writer requesting an already write-locked row—must wait until the holder commits or rolls back. Some locks protect a range against inserts. A plain snapshot read need not request such conflicting access.',[ev(my,'17.7.2.1, REPEATABLE READ and READ COMMITTED examples','Record/range locks can block writes; retained write locks make the second updater wait.'),ev(mv,'13.1, MVCC reading/writing and explicit locking paragraphs','Version-based reads and explicit locking have different blocking behavior.')])
edit('mechanisms','An isolation guarantee describes allowed observations and outcomes. Implementations can select old versions, delay incompatible access with locks, or detect unsafe read/write combinations and abort an attempt. PostgreSQL Serializable adds dependency monitoring to snapshots; its monitoring locks record dependencies without blocking.',[ev(pg,'13.2.3, opening and predicate-locking paragraphs','Serializable monitoring can trigger failure; predicate tracking does not itself block.'),ev(my,'17.7.2.1, SERIALIZABLE','InnoDB can convert ordinary SELECT into shared locking reads.'),ev(sq,'Isolation Between Database Connections; Isolation And Concurrency','SQLite permits one writer and rejects stale snapshot-to-write upgrades.')])
edit('statement_kind','Snapshot rules for plain SELECT do not fully describe UPDATE or a read requesting a lock. In PostgreSQL Read Committed, an updater can wait for a competing writer, then apply its operation to the newer row after rechecking WHERE. InnoDB likewise distinguishes nonlocking reads from locking statements.',[ev(pg,'13.2.1, UPDATE/DELETE/SELECT FOR UPDATE behavior','An updater waits and rechecks the updated row against its condition.'),ev(my,'17.7.2.1, REPEATABLE READ','Consistent SELECT and locking statements use different rules.')])
edit('engine','The engine, isolation level, and statement kind together determine behavior. PostgreSQL treats Read Uncommitted as Read Committed and prevents Repeatable Read phantoms. InnoDB SERIALIZABLE converts ordinary SELECT to shared locking reads when autocommit is disabled. SQLite ordinarily permits one writer; its WAL snapshots can reject a stale reader’s attempted write with SQLITE_BUSY_SNAPSHOT.',[ev(pg,'13.2 Table 13.1 and following paragraphs','PostgreSQL supplies stronger protections than level minimums.'),ev(my,'17.7.2.1 SERIALIZABLE','Autocommit condition controls shared locking conversion.'),ev(sq,'Isolation Between Database Connections; Isolation And Concurrency, X/Y write-upgrade example','Single writer and stale-snapshot rejection; shared-cache/read_uncommitted exception exists.')])
n['engine']['limits']=['SQLite uncommitted cross-connection reads require shared cache plus enabled read_uncommitted; default behavior excludes them.','WAL means write-ahead log: changes are appended separately so earlier readers retain their prior view.','These engine examples explain why guarantees differ; they are not a universal configuration recommendation.']
edit('retry','Waiting lets an existing attempt continue after another transaction finishes. A serialization failure instead rejects the attempt. PostgreSQL requires retrying the complete transaction, including reads and logic choosing SQL and values. Retrying only the final UPDATE can reuse the invalid decision. A retry may fail again.',[ev(rt,'13.5, complete transaction and completion paragraphs','Retry all decision logic; multiple attempts may be necessary.'),ev(pg,'13.2.1 updater waiting; 13.2.2 concurrent update failure','Waiting and aborting are distinct outcomes.')])
for id in ['transaction','serial','serializable','dirty','nonrepeatable','phantom','read_committed','repeatable_read']:
 for e in n[id]['evidence']:e['access']='Relevant HTML passage directly read in this run'
# Narrow the repeatable-read node so its own concept is not bundled with the serializability distinction.
n['repeatable_read']['answer']='In PostgreSQL Repeatable Read, ordinary reads retain the snapshot established by the first non-control statement, while seeing their own prior updates. Later commits by other transactions do not change that view; this also prevents phantom reads.'
n['repeatable_read']['evidence']=[ev(pg,'13.2.2, opening three paragraphs','Fixed first-statement snapshot, own updates, and stronger-than-minimum phantom protection.')]
new=[dict(id='stable_not_serial',question='Why can a stable snapshot still allow a serialization anomaly?',answer='A stable snapshot fixes each transaction’s view; it does not force other transactions’ decisions to agree with a single serial order. Transactions can read overlapping data, change different rows, and both commit. PostgreSQL Repeatable Read allows such outcomes; Serializable additionally checks the conflicting read/write dependencies.',status='supported',evidence=[ev(pg,'13.2.2 final explanation; 13.2.3 concurrent sums example','A stable snapshot can admit results inconsistent with every serial ordering.')]),dict(id='correctness_limit',question='When does serializable isolation preserve an application rule?',answer='Start from a state satisfying the rule, include each complete read/decision/write operation in one transaction, and make every relevant transaction preserve the rule when executed serially under the same guarantee. A serial-equivalent committed outcome then preserves it. Isolation does not invent the rule or repair logic that is wrong even when run alone.',status='supported',evidence=[ev(pg,'13.2.3, paragraph beginning “The guarantee that any set”','Individually correct serializable transactions compose into a correct serial-equivalent committed result.','reasoned consequence'),ev(tx,'3.4, transfer example','Related operations must be grouped into the intended complete transaction.')])]
g['nodes']+=new
n.update({x['id']:x for x in new})
edit('target','Individually valid read-dependent changes can combine into a result that violates an application rule when transactions overlap. Atomicity groups writes; isolation constrains observations and committed outcomes. Stronger levels prevent more anomalies, but stable snapshots alone are not serializability. With correct transaction boundaries and individually correct logic, consistent use of Serializable protects the serial-equivalent result; engines enforce guarantees using versions, locks, and possible abort/retry work.',[ev(pg,'13.2 table; 13.2.2–13.2.3','Synthesis of allowed anomalies, stable snapshot limits, and serializable composition.'),ev(tx,'3.4','Grouped updates supply atomicity.'),ev(rt,'13.5','Applications must repeat complete failed attempts.')])
# Remove edges that only made an example precede a definition; add actual claim prerequisites.
remove={('serial','wrong_result'),('wrong_result','repeatable_read')}
g['edges']=[e for e in g['edges'] if (e['from'],e['to']) not in remove]
for a,b,why in [
('repeatable_read','stable_not_serial','The distinction concerns the stable per-transaction view this level supplies.'),
('serializable','stable_not_serial','A serialization anomaly means failure of the serial-order outcome criterion.'),
('read_decision','stable_not_serial','Read-dependent writes can encode incompatible decisions despite each fixed view.'),
('stable_not_serial','target','The answer must explain why stable reads do not yet provide the strongest outcome guarantee.'),
('serializable','correctness_limit','Preservation is proved using an equivalent serial ordering of committed transactions.'),
('rule','correctness_limit','The invariant to preserve must be supplied independently of isolation.'),
('transaction','correctness_limit','The full decision and its writes must be inside the unit ordered by serializability.'),
('correctness_limit','target','The stated protection depends on valid transaction boundaries and correct serial logic.'),
('read_decision','retry','Whole-transaction retries must recompute the decisions that chose the writes.')]:g['edges'].append(dict(from_=a,to=b,why=why))
for e in g['edges']:
 if 'from_' in e:e['from']=e.pop('from_')
g['scope']='Prerequisite research graph only. Ordinary transactional table data on separate connections; SQL examples and engine differences retained. No claim of distributed external-side-effect atomicity, durability tuning, or universal performance ranking. No full report or renderer.'
g['revisions'].append(dict(round=2,timestamp=now,action='Direct source reading filled research gaps; split stable snapshot from serializability and added correctness conditions; removed two explanatory-order edges.'))
# Full before/after graph states make revisions reconstructable without relying on prose.
(p/'dag.round-2.json').write_text(json.dumps(g,indent=2)+'\n')
(p/'dag.json').write_text(json.dumps(g,indent=2)+'\n')
entry=dict(round=2,timestamp=now,event='research_and_revision',queries=[],opened=[pg,my,tx,sq],additional_sources=[mv,rt],findings=['Read relevant PG isolation passages including both complete worked examples, minimum-protection table, snapshot timing, and dependency monitoring.','Read MySQL level definitions, lock examples, and SERIALIZABLE autocommit qualification.','Read transaction tutorial and SQLite separate-connection, WAL, upgrade, and own-write passages.'],before_artifact='dag.initial.json',after_artifact='dag.round-2.json',edits=dict(nodes_changed=[x['id'] for x in g['nodes'] if x not in before['nodes']],edges_removed=[list(x) for x in remove],edges_added=[e for e in g['edges'] if e not in before['edges']]),remaining_gaps=[])
with (p/'history.jsonl').open('a') as f:f.write(json.dumps(entry)+'\n')
print('Saved researched graph:',len(g['nodes']),'nodes,',len(g['edges']),'edges')
